/**
 * @ignore
 * @method
 * @name binance#parseEvent
 * @description parses a raw binance market topic (with nested markets) into the unified event shape
 * @param {object} rawTopic the raw market topic object
 * @returns {object} an event structure
 */
func (this *BinanceCore) ParseEvent(rawTopic any) any {
	//
	//     {
	//         "marketTopicId": 4229564,
	//         "vendor": "PREDICT_FUN",
	//         "chainId": "56",
	//         "slug": "btc-price-1h-up-or-down",
	//         "title": "BTC Price 1h Up or Down?",
	//         "question": "Will BTC price go UP?",
	//         "description": "Resolves YES if BTC spot price is higher than the starting price.",
	//         "imageUrl": "https://...",
	//         "topicType": "FLAT",
	//         "chartType": "CRYPTO_UP_DOWN",
	//         "symbol": "BTCUSDT",
	//         "variantData": { "type": "CRYPTO_UP_DOWN", "startPrice": "67890.12", "endPrice": null },
	//         "participantCount": 3420,
	//         "collateral": "USDT",
	//         "feeRateBps": 200,
	//         "slippageBps": 1200,
	//         "tradeVolume": "158234.56",
	//         "liquidity": "45000.00",
	//         "publishedAt": 1748100000000,
	//         "startDate": 1748131200000,
	//         "endDate": 1748134800000,
	//         "status": "REGISTERED",
	//         "timeline": [ ... ],
	//         "markets": [ { "marketId": 5567895, "title": "UP", "outcomes": [ ... ] } ]
	//     }
	//
	var rawMarkets any = this.SafeList(rawTopic, "markets", []any{})
	var marketsList any = []any{}
	var anyActive bool = false
	var rawMarketsLength int = ccxt.GetArrayLength(rawMarkets)
	for i := 0; ccxt.IsLessThan(i, rawMarketsLength); i++ {
		var parsed any = this.ParseTopicMarket(ccxt.GetValue(rawMarkets, i), rawTopic)
		ccxt.AppendToArray(&marketsList, parsed)
		if ccxt.EvalTruthy(this.SafeBool(parsed, "active", false)) {
			anyActive = true
		}
	}
	var topicId *string = this.SafeString(rawTopic, "marketTopicId")
	var slug *string = this.SafeString(rawTopic, "slug")
	var title *string = this.SafeString(rawTopic, "title")
	var endDate *int64 = this.SafeInteger(rawTopic, "endDate")
	var created *int64 = this.SafeInteger2(rawTopic, "publishedAt", "startDate")
	var status *string = this.SafeString(rawTopic, "status")
	var active any = anyActive
	if rawMarketsLength == 0 {
		active = (status != nil && *status == "REGISTERED") || (status != nil && *status == "OPEN")
	}
	var resolved any = nil
	if status != nil {
		resolved = (status != nil && *status == "RESOLVED") || (status != nil && *status == "SETTLED")
	}
	return map[string]any{
		"id":              topicId,
		"slug":            slug,
		"event":           ccxt.Ternary((slug != nil), this.ShortenSlug(slug), nil),
		"title":           title,
		"description":     this.SafeString(rawTopic, "description"),
		"markets":         marketsList,
		"active":          active,
		"volume":          this.SafeNumber(rawTopic, "tradeVolume"),
		"liquidity":       this.SafeNumber(rawTopic, "liquidity"),
		"url":             nil,
		"image":           this.SafeString(rawTopic, "imageUrl"),
		"created":         created,
		"createdDatetime": this.Iso8601(created),
		"end":             endDate,
		"endDatetime":     this.Iso8601(endDate),
		"category":        this.SafeString(rawTopic, "chartType"),
		"resolved":        resolved,
		"info":            rawTopic,
	}
}

/**
 * @ignore
 * @method
 * @name binance#parseTopicMarket
 * @description parses one nested market of a market topic into the unified market shape, building its outcome tokens
 * @param {object} rawMarket the nested market object
 * @param {object} rawTopic the enclosing raw market topic (carries slug/vendor/fees/dates)
 * @returns {object} a market structure
 */
func (this *BinanceCore) ParseTopicMarket(rawMarket any, rawTopic any) any {
	//
	//     {
	//         "marketId": 5567895,
	//         "externalId": "ext_001",
	//         "title": "UP",
	//         "question": "Will BTC go UP?",
	//         "description": "Resolves YES if BTC price increases.",
	//         "conditionId": "0xabc123",
	//         "status": "REGISTERED",
	//         "tradingStatus": "OPEN",
	//         "tradeVolume": "90000.00",
	//         "liquidity": "25000.00",
	//         "decimalPrecision": 2,
	//         "outcomes": [
	//             { "name": "YES", "price": "0.52", "chance": "0.52", "index": 0, "tokenId": "112233" }
	//         ]
	//     }
	//
	var marketId *string = this.SafeString(rawMarket, "marketId")
	var topicId *string = this.SafeString(rawTopic, "marketTopicId")
	var topicSlug *string = this.SafeString(rawTopic, "slug")
	var vendor *string = this.SafeString(rawTopic, "vendor")
	var collateral *string = this.SafeString(rawTopic, "collateral", "USDT")
	var title *string = this.SafeString(rawMarket, "title", marketId)
	var marketSymbol any = this.SlugToMarketSymbol(topicSlug, title)
	var tradingStatus *string = this.SafeString(rawMarket, "tradingStatus")
	var status *string = this.SafeString(rawMarket, "status")
	var active bool = (tradingStatus != nil && *tradingStatus == "OPEN")
	if tradingStatus == nil {
		active = (status != nil && *status == "REGISTERED") || (status != nil && *status == "OPEN")
	}
	var resolved bool = (status != nil && *status == "RESOLVED") || (status != nil && *status == "SETTLED")
	var endDate *int64 = this.SafeInteger(rawTopic, "endDate")
	var feeRateBps *string = this.SafeString(rawTopic, "feeRateBps", "200")
	var feeRate any = this.ParseNumber(ccxt.Precise.StringDiv(feeRateBps, "10000"))
	var decimalPrecision *string = this.SafeString(rawMarket, "decimalPrecision", "2")
	var pricePrecision any = this.ParseNumber(this.ParsePrecision(decimalPrecision))
	var precision map[string]any = map[string]any{
		"amount": 0.01,
		"price":  pricePrecision,
	}
	var volume any = this.SafeNumber(rawMarket, "tradeVolume")
	var liquidity any = this.SafeNumber(rawMarket, "liquidity")
	var rawOutcomes any = this.SafeList(rawMarket, "outcomes", []any{})
	var outcomes any = []any{}
	var resolvedOutcomeRaw any = nil
	var rawOutcomesLength int = ccxt.GetArrayLength(rawOutcomes)
	for oi := 0; ccxt.IsLessThan(oi, rawOutcomesLength); oi++ {
		var rawOutcome any = ccxt.GetValue(rawOutcomes, oi)
		var label *string = this.SafeStringUpper(rawOutcome, "name")
		var tokenId *string = this.SafeString(rawOutcome, "tokenId")
		var outcomeHandle any = ccxt.Add(ccxt.Add(marketSymbol, ":"), label)
		var price *string = this.SafeString(rawOutcome, "price")
		var winnerRaw any = nil
		var settleFractionRaw any = nil
		if resolved && (price != nil) {
			winnerRaw = ccxt.Precise.StringEq(price, "1")
			settleFractionRaw = ccxt.Ternary(ccxt.EvalTruthy((winnerRaw)), 1, 0)
			if ccxt.EvalTruthy(winnerRaw) {
				resolvedOutcomeRaw = outcomeHandle
			}
		}
		var winner any = winnerRaw
		var settleFraction any = settleFractionRaw
		ccxt.AppendToArray(&outcomes, map[string]any{
			"id":             tokenId,
			"outcomeId":      tokenId,
			"outcome":        outcomeHandle,
			"market":         marketSymbol,
			"label":          label,
			"price":          this.ParseNumber(price),
			"active":         active,
			"winner":         winner,
			"settleFraction": settleFraction,
			"precision":      precision,
			"info": map[string]any{
				"tokenId":       tokenId,
				"marketId":      marketId,
				"marketTopicId": topicId,
				"vendor":        vendor,
				"chainId":       this.SafeString(rawTopic, "chainId"),
				"slug":          topicSlug,
				"marketTitle":   title,
				"outcomeLabel":  label,
				"index":         this.SafeString(rawOutcome, "index"),
				"price":         price,
				"chance":        this.SafeString(rawOutcome, "chance"),
				"collateral":    collateral,
				"feeRateBps":    feeRateBps,
				"slippageBps":   this.SafeString(rawTopic, "slippageBps"),
				"conditionId":   this.SafeString(rawMarket, "conditionId"),
				"externalId":    this.SafeString(rawMarket, "externalId"),
			},
		})
	}
	var resolvedOutcome any = resolvedOutcomeRaw
	return map[string]any{
		"id":              marketId,
		"market":          marketSymbol,
		"base":            collateral,
		"quote":           collateral,
		"settle":          nil,
		"baseId":          marketId,
		"quoteId":         collateral,
		"settleId":        nil,
		"type":            "prediction",
		"marketType":      "binary",
		"executionModel":  "clob",
		"collateral":      collateral,
		"spot":            false,
		"margin":          false,
		"swap":            false,
		"future":          false,
		"option":          false,
		"prediction":      true,
		"active":          active,
		"resolved":        resolved,
		"resolvedOutcome": resolvedOutcome,
		"contract":        false,
		"linear":          nil,
		"inverse":         nil,
		"contractSize":    nil,
		"expiry":          endDate,
		"expiryDatetime":  this.Iso8601(endDate),
		"strike":          nil,
		"optionType":      nil,
		"taker":           feeRate,
		"maker":           0,
		"percentage":      true,
		"tierBased":       false,
		"feeSide":         "get",
		"precision":       precision,
		"limits": map[string]any{
			"leverage": map[string]any{
				"min": 1,
				"max": 1,
			},
			"amount": map[string]any{
				"min": nil,
				"max": nil,
			},
			"price": map[string]any{
				"min": 0.01,
				"max": 0.99,
			},
			"cost": map[string]any{
				"min": 1.5,
				"max": nil,
			},
		},
		"outcomes": outcomes,
		"info": this.Extend(rawMarket, map[string]any{
			"marketTopicId": topicId,
			"vendor":        vendor,
			"slug":          topicSlug,
			"volume":        volume,
			"liquidity":     liquidity,
		}),
		"created": this.SafeInteger(rawTopic, "publishedAt"),
	}
}

